  [25895] = { "対象と同じクラスのレイドまたはグループのメンバー全員にGreater Blessing of Salvationを与え、$D1の間発生させるすべての脅威を$N1%減少させます。プレイヤーが同時に受けられるBlessingは、パラディン一人につき一つだけです。", "発生する脅威が$N1%減少します。", 0xa9c3aed0, 0x69005136, "uu" },
  [25898] = { "対象と同じクラスのレイドまたはグループのメンバー全員にGreater Blessing of Kingsを与え、$D1の間すべての能力値を$N1%上昇させます。プレイヤーが同時に受けられるBlessingは、パラディン一人につき一つだけです。", "能力値が$N1%上昇します。", 0xb22009f7, 0xb6c88837, "uu" },
  [25902] = { "$N1のHolyダメージを与えます。", nil, 0x4e0fafde, nil, "um" },
  [25903] = { "$N1回復します。", nil, 0xb1a62d77, nil, "um" },
  [25906] = { "有害な呪文が命中したとき、一定の確率で$D1の間、呪文と効果のダメージを$N1増加させます。", nil, 0x36b635c4, nil, "um" },
  [25911] = { "$N1のHolyダメージを与えます。", nil, 0x4e0fafde, nil, "um" },
  [25912] = { "$N1のHolyダメージを与えます。", nil, 0x4e0fafde, nil, "um" },
