  [25914] = { "$N1回復します。", nil, 0xb1a62d77, nil, "um" },
  [25916] = { "対象と同じクラスのレイドまたはグループのメンバー全員にGreater Blessing of Mightを与え、$D1の間近接攻撃力を$N1上昇させます。プレイヤーが同時に受けられるBlessingは、パラディン一人につき一つだけです。", "近接攻撃力が$N1上昇します。", 0xe7fcf2ba, 0x92e5f308, "uu" },
  [25918] = { "対象と同じクラスのレイドまたはグループのメンバー全員にGreater Blessing of Wisdomを与え、$D1の間$N2秒ごとにマナを$N1回復させます。プレイヤーが同時に受けられるBlessingは、パラディン一人につき一つだけです。", "$N2秒ごとにマナを$N1回復します。", 0xcc83a598, 0xb1bbeede, "uu" },
  [25953] = { "高周波音を発し、Temple of \nAhn'Qirajの下にある巣穴からsilithid \ntankを出てこさせます。出てきた\nsilithidは召喚者に従順で、Temple \nof Ahn'Qiraj内で乗り物として使えます。\n乗り手が攻撃を受けるとsilithid \ntankは地下へ追い返されます。", "地上での移動速度が$N1%上昇します。", 0x78dbdc3f, 0x2195529a, "uu" },
  [25954] = { "$N2秒間でHealthを$N1回復。食事中は\n座っている必要があります。\n10秒以上食事をするとお腹いっぱいになり15分間StaminaとSpiritが$N4上がります。", nil, 0x6651748e, nil, "um" },
  [25956] = { "Judgementのクールダウンを$N1秒短縮します。", nil, 0xefa5622e, nil, "um" },
  [25990] = { "$D1の間、毎秒体力とマナの$N1%を回復します。回復中は座っている必要があります。フルーツケーキの味も好きなほうがいいでしょう。", "毎秒体力とマナの$N1%を回復します。うーん……フルーツケーキ……", 0x29f111a1, 0xac1faf0a, "uu" },
